function markdown(source) {
    if (source.includes("| Q |")) {
        const lines = source.trim().split("\n");
        const rows = lines.slice(3).map((line) => line.split("|").slice(1, -1).map((value) => value.trim()));
        return h(Fragment, null,
            h("h2", null, "Final Answer"),
            h("table", null,
                h("thead", null,
                    h("tr", null,
                        h("th", null, "Q"),
                        h("th", null, "Answer Summary"))),
                h("tbody", null, rows.map((row, index) => h("tr", { key: index }, row.map((value, column) => h("td", { key: column }, value)))))));
    }
    return source.split("\n").filter((line) => line.trim()).map((line, index) => {
        const value = line.replace(/^#+\s*/, "").replace(/\*\*/g, "").replace(/^\*|\*$/g, "");
        if (line.startsWith("###"))
            return h("h3", { key: index }, value);
        if (line.startsWith("##"))
            return h("h2", { key: index }, value);
        if (line.startsWith("#"))
            return h("h1", { key: index }, value);
        return h("p", { key: index }, value);
    });
}
